"use client";

import { Plus } from "lucide-react";
import { useState } from "react";
import { Sheet } from "@/components/kit/sheet";
import { PendingButton } from "@/components/kit/button";
import { Chip } from "@/components/kit/segmented";
import { InlineError } from "@/components/kit/feedback";
import { notify } from "@/components/kit/toast";
import { PROJECTS, useTasks, type Due, type Priority } from "@/lib/tasks";

const DUES: { value: Due; label: string }[] = [
  { value: "today", label: "今日" },
  { value: "tomorrow", label: "明日" },
  { value: "week", label: "今週" },
  { value: "later", label: "日付なし" },
];

export function AddTaskSheet({ open, onOpenChange }: { open: boolean; onOpenChange: (o: boolean) => void }) {
  return (
    <Sheet open={open} onOpenChange={onOpenChange} title="タスクを追加">
      {/* 閉じるたびに入力を空に戻すため、開いている間だけ中身を作る */}
      {open && <AddTaskForm onDone={() => onOpenChange(false)} />}
    </Sheet>
  );
}

function AddTaskForm({ onDone }: { onDone: () => void }) {
  const { add, undo } = useTasks();
  const [title, setTitle] = useState("");
  const [due, setDue] = useState<Due>("today");
  const [project, setProject] = useState(PROJECTS[0]);
  const [priority, setPriority] = useState<Priority>("中");
  const [error, setError] = useState(false);
  const [pending, setPending] = useState(false);

  return (
    <form
      noValidate
      className="grid gap-4"
      onSubmit={(e) => {
        e.preventDefault();
        if (pending) return;
        const v = title.trim();
        if (!v) {
          setError(true);
          document.getElementById("task-title")?.focus();
          return;
        }
        setPending(true);
        // 保存にかかる時間の見本（本番ではデータベースへの保存を待つ）
        setTimeout(() => {
          add({ title: v, due, project, priority, note: "" });
          onDone();
          notify(`「${v}」を追加しました`, undo);
        }, 600);
      }}
    >
      <div className="grid gap-1.5">
        <label htmlFor="task-title" className="text-sm text-fg-2">
          タスク名
        </label>
        <input
          id="task-title"
          value={title}
          onChange={(e) => {
            setTitle(e.target.value);
            setError(false);
          }}
          placeholder="見積書を送る"
          autoComplete="off"
          aria-invalid={error || undefined}
          aria-describedby={error ? "task-title-error" : undefined}
          className="h-hit w-full rounded-sm border border-line bg-canvas px-3 outline-none focus:border-accent focus:ring-2 focus:ring-accent/25 aria-invalid:border-danger"
        />
        {error && <InlineError>タスク名を入れてください</InlineError>}
      </div>

      <fieldset className="grid gap-1.5">
        <legend className="mb-1.5 text-sm text-fg-2">期限</legend>
        <div className="flex flex-wrap gap-1.5">
          {DUES.map((d) => (
            <Chip key={d.value} pressed={due === d.value} onClick={() => setDue(d.value)}>
              {d.label}
            </Chip>
          ))}
        </div>
      </fieldset>

      <div className="grid gap-1.5">
        <label htmlFor="task-project" className="text-sm text-fg-2">
          案件
        </label>
        <select
          id="task-project"
          value={project}
          onChange={(e) => setProject(e.target.value)}
          className="h-hit w-full rounded-sm border border-line bg-canvas px-3 outline-none focus:border-accent focus:ring-2 focus:ring-accent/25"
        >
          {PROJECTS.map((p) => (
            <option key={p}>{p}</option>
          ))}
        </select>
      </div>

      <fieldset className="grid gap-1.5">
        <legend className="mb-1.5 text-sm text-fg-2">優先度</legend>
        <div className="flex flex-wrap gap-1.5">
          {(["高", "中", "低"] as Priority[]).map((p) => (
            <Chip key={p} pressed={priority === p} onClick={() => setPriority(p)}>
              {p}
            </Chip>
          ))}
        </div>
      </fieldset>

      <PendingButton type="submit" variant="primary" size="lg" pending={pending} pendingLabel="追加しています…" className="mt-1 w-full">
        <Plus aria-hidden size={18} />
        追加する
      </PendingButton>
    </form>
  );
}

"use client";

/**
 * タスク1件への操作（完了・今日やる・明日に回す・削除）。どの画面から操作しても、同じ文面でお知らせ＋「取り消す」が出る。
 *   マウス … 行の「…」ボタンでメニュー（キーボードの矢印でも選べる）
 *   指     … 行・カードの長押し、または「…」で下から操作シート
 * 削除も取り消せるので、確認ダイアログは挟まない（元に戻せない操作だけ確認する）。
 */
import { Menu } from "@base-ui/react/menu";
import { ArrowRight, Check, FileText, MoreHorizontal, RotateCcw, Sun, Trash2, type LucideIcon } from "lucide-react";
import { Sheet } from "@/components/kit/sheet";
import { notify } from "@/components/kit/toast";
import { useCoarsePointer } from "@/lib/prefs";
import { useTasks, type Task } from "@/lib/tasks";
import { cn } from "@/lib/cn";

export function useTaskCommands() {
  const { toggle, setDue, remove, undo } = useTasks();
  return {
    toggle: (t: Task) => {
      const r = toggle(t.id);
      if (r) notify(r.done ? `「${r.title}」を完了にしました` : "未完了に戻しました", undo);
    },
    today: (t: Task) => {
      setDue([t.id], "today");
      notify("今日のタスクに入れました", undo);
    },
    tomorrow: (t: Task) => {
      setDue([t.id], "tomorrow");
      notify("明日に回しました", undo);
    },
    remove: (t: Task) => {
      remove(t.id);
      notify(`「${t.title}」を削除しました`, undo);
    },
  };
}

type Action = { key: string; label: string; icon: LucideIcon; run: () => void; danger?: boolean };

function useActionList(task: Task | null, onOpenDetail?: (t: Task) => void): Action[] {
  const cmd = useTaskCommands();
  if (!task) return [];
  const list: Action[] = [
    { key: "toggle", label: task.done ? "未完了に戻す" : "完了にする", icon: task.done ? RotateCcw : Check, run: () => cmd.toggle(task) },
  ];
  if (!task.done && task.due !== "today") list.push({ key: "today", label: "今日やる", icon: Sun, run: () => cmd.today(task) });
  if (!task.done && (task.due === "today" || task.due === "overdue")) list.push({ key: "tomorrow", label: "明日に回す", icon: ArrowRight, run: () => cmd.tomorrow(task) });
  if (onOpenDetail) list.push({ key: "detail", label: "詳細を見る", icon: FileText, run: () => onOpenDetail(task) });
  list.push({ key: "delete", label: "削除", icon: Trash2, run: () => cmd.remove(task), danger: true });
  return list;
}

/**
 * 指で触る端末の操作シート（長押し・… から開く）。
 * 閉じる動きの間も中身を出しておくため、task は閉じた後も残し、開閉は open で渡す。
 */
export function TaskActionSheet({
  task,
  open,
  onOpenChange,
  onOpenDetail,
}: {
  task: Task | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onOpenDetail?: (t: Task) => void;
}) {
  const actions = useActionList(task, onOpenDetail);
  return (
    <Sheet open={open && !!task} onOpenChange={onOpenChange} title={task?.title ?? ""} description="このタスクへの操作">
      <div className="grid gap-1 pb-2">
        {actions.map((a) => (
          <button
            key={a.key}
            type="button"
            onClick={() => {
              onOpenChange(false);
              a.run();
            }}
            className={cn(
              "flex min-h-row items-center gap-3 rounded-md px-3 text-left text-base transition-colors duration-[var(--wk-dur-fast)] active:bg-surface-2",
              a.danger ? "text-danger" : "text-fg",
            )}
          >
            <a.icon aria-hidden size={20} className={a.danger ? "" : "text-fg-2"} />
            {a.label}
          </button>
        ))}
      </div>
    </Sheet>
  );
}

/** 行の「…」ボタン。マウスではその場のメニュー、指では操作シートを開く */
export function TaskMoreButton({ task, onSheet, onOpenDetail }: { task: Task; onSheet: (t: Task) => void; onOpenDetail?: (t: Task) => void }) {
  const coarse = useCoarsePointer();
  const actions = useActionList(task, onOpenDetail);
  const triggerClass =
    "relative z-10 grid size-hit flex-none place-items-center rounded-md text-fg-3 transition-colors duration-[var(--wk-dur-fast)] hover:bg-surface-2 hover:text-fg data-[popup-open]:bg-surface-2 data-[popup-open]:text-fg";
  const label = `「${task.title}」の操作`;

  if (coarse) {
    return (
      <button type="button" data-no-longpress aria-label={label} onClick={() => onSheet(task)} className={triggerClass}>
        <MoreHorizontal aria-hidden size={18} />
      </button>
    );
  }
  return (
    <Menu.Root>
      <Menu.Trigger aria-label={label} className={triggerClass}>
        <MoreHorizontal aria-hidden size={18} />
      </Menu.Trigger>
      <Menu.Portal>
        <Menu.Positioner sideOffset={4} align="end" className="z-50 outline-none">
          <Menu.Popup className="min-w-44 origin-[var(--transform-origin)] rounded-md border border-line bg-surface p-1 shadow-float outline-none transition-[opacity,scale] duration-[var(--wk-dur-fast)] ease-out data-[ending-style]:scale-95 data-[ending-style]:opacity-0 data-[starting-style]:scale-95 data-[starting-style]:opacity-0">
            {actions.map((a) => (
              <Menu.Item
                key={a.key}
                onClick={a.run}
                className={cn(
                  "flex h-hit cursor-default items-center gap-2.5 rounded-sm px-2.5 text-sm outline-none select-none data-[highlighted]:bg-surface-2",
                  a.danger ? "text-danger" : "text-fg",
                )}
              >
                <a.icon aria-hidden size={16} className={a.danger ? "" : "text-fg-3"} />
                {a.label}
              </Menu.Item>
            ))}
          </Menu.Popup>
        </Menu.Positioner>
      </Menu.Portal>
    </Menu.Root>
  );
}

"use client";

/**
 * タスクの詳細。PC（1280px 以上）は一覧の右のパネル、それより狭いときはシートに同じ中身を出す。
 * よく使う操作（完了・今日やる）は大きいボタン、削除は控えめな文字のボタンにする。
 */
import { ArrowRight, Check, ListChecks, RotateCcw, Sun, Trash2 } from "lucide-react";
import { Button } from "@/components/kit/button";
import { EmptyState } from "@/components/kit/feedback";
import { Sheet } from "@/components/kit/sheet";
import { CheckButton, DueTag, PriorityTag } from "./task-parts";
import { useTaskCommands } from "./task-actions";
import type { Task } from "@/lib/tasks";
import { cn } from "@/lib/cn";

export function TaskDetail({ task, onRemoved }: { task: Task | null; onRemoved?: () => void }) {
  const cmd = useTaskCommands();
  if (!task) return <EmptyState icon={ListChecks} title="タスクを選ぶと、ここに詳細が出ます" body="一覧の行をクリックするか、↑↓ キーで選べます。" />;

  return (
    <div className="grid gap-5">
      <div className="-ml-2 flex items-start gap-1">
        <CheckButton task={task} onToggle={() => cmd.toggle(task)} />
        <h2 className={cn("pt-1.5 text-lg leading-snug font-semibold", task.done && "text-fg-3 line-through")}>{task.title}</h2>
      </div>
      <dl className="grid grid-cols-[5.5em_1fr] items-center gap-x-3 gap-y-3 text-sm">
        <dt className="text-fg-3">期限</dt>
        <dd>
          <DueTag task={task} />
        </dd>
        <dt className="text-fg-3">案件</dt>
        <dd>{task.project}</dd>
        <dt className="text-fg-3">優先度</dt>
        <dd>
          <PriorityTag task={task} />
        </dd>
        <dt className="text-fg-3">状態</dt>
        <dd>{task.done ? <span className="text-ok">完了</span> : "未完了"}</dd>
      </dl>
      {task.note && <p className="rounded-md bg-surface-2 px-3.5 py-3 text-sm whitespace-pre-wrap text-fg-2">{task.note}</p>}
      <div className="flex flex-wrap gap-2">
        {task.done ? (
          <Button onClick={() => cmd.toggle(task)}>
            <RotateCcw aria-hidden size={16} />
            未完了に戻す
          </Button>
        ) : (
          <Button variant="primary" onClick={() => cmd.toggle(task)}>
            <Check aria-hidden size={16} />
            完了にする
          </Button>
        )}
        {!task.done && task.due !== "today" && (
          <Button onClick={() => cmd.today(task)}>
            <Sun aria-hidden size={16} />
            今日やる
          </Button>
        )}
        {!task.done && (task.due === "today" || task.due === "overdue") && (
          <Button onClick={() => cmd.tomorrow(task)}>
            <ArrowRight aria-hidden size={16} />
            明日に回す
          </Button>
        )}
        <Button
          variant="danger"
          onClick={() => {
            cmd.remove(task);
            onRemoved?.();
          }}
        >
          <Trash2 aria-hidden size={16} />
          削除
        </Button>
      </div>
    </div>
  );
}

/** 狭い画面で詳細を出すシート（閉じる動きの間も中身を出すため、task と open は別に渡す） */
export function TaskDetailSheet({ task, open, onOpenChange }: { task: Task | null; open: boolean; onOpenChange: (open: boolean) => void }) {
  return (
    <Sheet open={open && !!task} onOpenChange={onOpenChange} title="タスクの詳細">
      <div className="pt-1">
        <TaskDetail task={task} onRemoved={() => onOpenChange(false)} />
      </div>
    </Sheet>
  );
}

"use client";

import { Check } from "lucide-react";
import { DUE_LABEL, type Task } from "@/lib/tasks";
import { cn } from "@/lib/cn";

/** 丸いチェック。押せる範囲は 36px（指なら 44px）、見た目の丸は 20px */
export function CheckButton({ task, onToggle }: { task: Task; onToggle: () => void }) {
  return (
    <button
      type="button"
      aria-label={task.done ? `「${task.title}」を未完了に戻す` : `「${task.title}」を完了にする`}
      aria-pressed={task.done}
      data-no-longpress
      onClick={(e) => {
        e.stopPropagation();
        onToggle();
      }}
      className="group relative z-10 grid size-hit flex-none place-items-center rounded-full"
    >
      <span
        className={cn(
          "grid size-5 place-items-center rounded-full border-[1.8px] transition-[background-color,border-color,transform] duration-[var(--wk-dur-base)] ease-out group-active:scale-85",
          task.done ? "border-accent bg-accent" : "border-fg-3",
        )}
      >
        <Check
          aria-hidden
          size={13}
          strokeWidth={3}
          className={cn("text-on-accent transition-[opacity,scale] duration-[var(--wk-dur-base)] ease-out", task.done ? "scale-100 opacity-100" : "scale-40 opacity-0")}
        />
      </span>
    </button>
  );
}

export function DueTag({ task }: { task: Task }) {
  const tone = task.done ? "" : task.due === "overdue" ? "bg-danger-soft text-danger" : task.due === "today" ? "bg-accent-soft text-accent-text" : "";
  return <span className={cn("inline-flex items-center rounded-full bg-surface-2 px-2 py-1 text-xs leading-none whitespace-nowrap text-fg-2", tone)}>{DUE_LABEL[task.due]}</span>;
}

export function ProjectTag({ name }: { name: string }) {
  return <span className="inline-flex items-center rounded-full bg-surface-2 px-2 py-1 text-xs leading-none whitespace-nowrap text-fg-2">{name}</span>;
}

export function PriorityTag({ task }: { task: Task }) {
  const dot = task.priority === "高" ? "bg-danger" : task.priority === "中" ? "bg-warn" : "bg-fg-3";
  return (
    <span className="inline-flex items-center gap-1.5 text-xs whitespace-nowrap text-fg-2">
      <span aria-hidden className={cn("size-2 rounded-full", dot)} />
      優先度 {task.priority}
    </span>
  );
}

/**
 * タスクのカード（今日の画面で使う大きめの形）。
 * カード全体が「詳細を開く」ボタン（題名のボタンを全面に広げている）。チェックだけは別に押せる。
 * 指の端末では長押しで操作シート（bind に useLongPress の bind を渡す）。
 */
export function TaskCard({
  task,
  onToggle,
  onOpen,
  bind,
}: {
  task: Task;
  onToggle: () => void;
  onOpen?: () => void;
  bind?: React.HTMLAttributes<HTMLDivElement>;
}) {
  return (
    <div
      {...bind}
      className="relative flex items-center gap-1.5 rounded-md border border-line bg-surface py-2 pr-3 pl-1.5 transition-[transform,background-color] duration-[var(--wk-dur-fast)] ease-out select-none has-[[data-open]:active]:scale-[0.985] has-[[data-open]:active]:duration-[var(--wk-dur-press)] data-[held]:scale-[0.96] data-[held]:bg-surface-2 [-webkit-touch-callout:none]"
    >
      <CheckButton task={task} onToggle={onToggle} />
      <div className="grid min-w-0 flex-1 gap-1.5 py-1">
        {onOpen ? (
          <button
            type="button"
            data-open
            onClick={onOpen}
            className={cn("text-left text-base font-medium after:absolute after:inset-0 after:rounded-md focus-visible:outline-none focus-visible:after:outline-2 focus-visible:after:outline-accent", task.done && "text-fg-3 line-through")}
          >
            {task.title}
          </button>
        ) : (
          <span className={cn("text-base font-medium", task.done && "text-fg-3 line-through")}>{task.title}</span>
        )}
        <span className="flex flex-wrap items-center gap-1.5">
          <DueTag task={task} />
          <ProjectTag name={task.project} />
          <PriorityTag task={task} />
        </span>
      </div>
    </div>
  );
}

"use client";

/**
 * カードを押したら詳細シート、長押し（または …）で操作シート、を1か所で持つ。
 * 操作シートの「詳細を見る」は、操作シートが閉じ切ってから詳細シートを開く（シートを2枚重ねない）。
 */
import { useReducedMotion } from "motion/react";
import { useState } from "react";
import { useTasks, type Task } from "@/lib/tasks";
import { TaskActionSheet } from "./task-actions";
import { TaskDetailSheet } from "./task-detail";

export function useTaskSheets() {
  const { tasks } = useTasks();
  const reduce = useReducedMotion();
  const [detail, setDetail] = useState<{ id: number; open: boolean } | null>(null);
  const [actions, setActions] = useState<{ id: number; open: boolean } | null>(null);
  const find = (id?: number) => (id === undefined ? null : (tasks.find((t) => t.id === id) ?? null));

  const openDetail = (t: Task) => setDetail({ id: t.id, open: true });
  const openActions = (t: Task) => setActions({ id: t.id, open: true });

  const sheets = (
    <>
      <TaskDetailSheet task={find(detail?.id)} open={!!detail?.open} onOpenChange={(open) => setDetail((d) => d && { ...d, open })} />
      <TaskActionSheet
        task={find(actions?.id)}
        open={!!actions?.open}
        onOpenChange={(open) => setActions((a) => a && { ...a, open })}
        onOpenDetail={(t) => setTimeout(() => openDetail(t), reduce ? 0 : 280)}
      />
    </>
  );
  return { openDetail, openActions, sheets };
}

"use client";

/**
 * 「今日を締める」手順フォーム（B 現場型の見本）。1回に1つだけ聞き、3つの手順で終える。
 *   1. 残ったタスク … 明日に回すものに印を付ける（最初は全部に印）
 *   2. ひとこと     … 今日のメモ（書かなくてもよい）
 *   3. 確認         … まとめを見て「締める」
 * 手順の途中で閉じても、もう一度開けば最初からやり直せる（途中の入力は捨てる）。
 */
import { ArrowLeft, ArrowRight, Check, MoonStar } from "lucide-react";
import { useState } from "react";
import { Button, PendingButton } from "@/components/kit/button";
import { Sheet } from "@/components/kit/sheet";
import { Steps } from "@/components/kit/steps";
import { notify } from "@/components/kit/toast";
import { useTasks } from "@/lib/tasks";
import { cn } from "@/lib/cn";

const STEPS = ["残ったタスク", "ひとこと", "確認"];

export function WrapUpSheet({ open, onOpenChange }: { open: boolean; onOpenChange: (open: boolean) => void }) {
  return (
    <Sheet open={open} onOpenChange={onOpenChange} title="今日を締める" description="残りを明日に回して、今日を終えます">
      {open && <WrapUpForm onDone={() => onOpenChange(false)} />}
    </Sheet>
  );
}

function WrapUpForm({ onDone }: { onDone: () => void }) {
  const { tasks, setDue, undo } = useTasks();
  const left = tasks.filter((t) => !t.done && (t.due === "today" || t.due === "overdue"));
  const doneToday = tasks.filter((t) => t.done && (t.due === "today" || t.due === "overdue")).length;
  const [step, setStep] = useState(0);
  const [moving, setMoving] = useState<number[]>(() => left.map((t) => t.id));
  const [memo, setMemo] = useState("");
  const [pending, setPending] = useState(false);

  const flip = (id: number) => setMoving((m) => (m.includes(id) ? m.filter((x) => x !== id) : [...m, id]));

  return (
    <div className="grid gap-5">
      <Steps steps={STEPS} current={step} onJump={setStep} />

      {step === 0 && (
        <fieldset className="grid gap-2">
          <legend className="mb-2 text-sm text-fg-2">明日に回すタスクに印を付けてください</legend>
          {left.length ? (
            left.map((t) => {
              const on = moving.includes(t.id);
              return (
                <label
                  key={t.id}
                  className={cn(
                    "flex min-h-row cursor-pointer items-center gap-3 rounded-md border px-3 transition-colors duration-[var(--wk-dur-fast)]",
                    on ? "border-accent bg-accent-soft" : "border-line bg-surface",
                  )}
                >
                  <input type="checkbox" checked={on} onChange={() => flip(t.id)} className="size-5 flex-none accent-[var(--wk-accent)]" />
                  <span className="min-w-0 flex-1 text-sm">{t.title}</span>
                  {t.due === "overdue" && <span className="text-xs text-danger">期限切れ</span>}
                </label>
              );
            })
          ) : (
            <p className="rounded-md bg-surface-2 px-3.5 py-3 text-sm text-fg-2">今日のタスクは全部終わっています。このまま次へ進んでください。</p>
          )}
        </fieldset>
      )}

      {step === 1 && (
        <div className="grid gap-1.5">
          <label htmlFor="wrap-memo" className="text-sm text-fg-2">
            今日のひとこと（書かなくても締められます）
          </label>
          <textarea
            id="wrap-memo"
            rows={4}
            value={memo}
            onChange={(e) => setMemo(e.target.value)}
            placeholder="よかったこと・明日の自分への申し送り"
            className="w-full resize-none rounded-sm border border-line bg-canvas px-3 py-2.5 leading-relaxed outline-none focus:border-accent focus:ring-2 focus:ring-accent/25"
          />
        </div>
      )}

      {step === 2 && (
        <dl className="grid grid-cols-[7em_1fr] gap-x-3 gap-y-2.5 rounded-md bg-surface-2 px-4 py-3.5 text-sm">
          <dt className="text-fg-3">終えたタスク</dt>
          <dd className="num">{doneToday}件</dd>
          <dt className="text-fg-3">明日に回す</dt>
          <dd className="num">{moving.length}件</dd>
          <dt className="text-fg-3">ひとこと</dt>
          <dd className="whitespace-pre-wrap">{memo.trim() || "なし"}</dd>
        </dl>
      )}

      <div className="flex gap-2">
        {step > 0 && (
          <Button variant="ghost" size="lg" onClick={() => setStep(step - 1)}>
            <ArrowLeft aria-hidden size={18} />
            戻る
          </Button>
        )}
        {step < STEPS.length - 1 ? (
          <Button variant="primary" size="lg" className="flex-1" onClick={() => setStep(step + 1)}>
            次へ
            <ArrowRight aria-hidden size={18} />
          </Button>
        ) : (
          <PendingButton
            variant="primary"
            size="lg"
            className="flex-1"
            pending={pending}
            pendingLabel="締めています…"
            onClick={() => {
              setPending(true);
              // 保存にかかる時間の見本（本番ではデータベースへの保存を待つ）
              setTimeout(() => {
                if (moving.length) setDue(moving, "tomorrow");
                onDone();
                notify(moving.length ? `今日を締めました。${moving.length}件を明日に回しました` : "今日を締めました。おつかれさまでした", moving.length ? undo : undefined);
              }, 600);
            }}
          >
            {moving.length ? <Check aria-hidden size={18} /> : <MoonStar aria-hidden size={18} />}
            締める
          </PendingButton>
        )}
      </div>
    </div>
  );
}

"use client";

/**
 * AI に相談（C AI相棒型）。
 *   会話は左（スマホでは全幅）、AI が作った表や計画（成果物）は
 *     1280px 以上 … 右のパネルに並べる
 *     それより狭い … 会話の中のカードを押すとシートで開く
 *   返事は文字が少しずつ届く（動きを減らす設定では一度に出す）。届いている間は次の依頼を受け付けない。
 *   過去の会話は「履歴」から開く。
 * 返事の中身は lib/ai-script.ts の台本。本番ではそこを AI の呼び出しに差し替える。
 */
import { ArrowUp, ChevronRight, ClipboardCopy, FileText, History, MessageSquarePlus, Sparkles, Sun } from "lucide-react";
import { useReducedMotion } from "motion/react";
import { useEffect, useRef, useState } from "react";
import { Button } from "@/components/kit/button";
import { EmptyState, InlineError, Page, PageHeader } from "@/components/kit/feedback";
import { Sheet } from "@/components/kit/sheet";
import { notify } from "@/components/kit/toast";
import { SAMPLE_HISTORY, SUGGESTIONS, answer, type Artifact } from "@/lib/ai-script";
import { useCoarsePointer, useWide } from "@/lib/prefs";
import { useTasks } from "@/lib/tasks";
import { cn } from "@/lib/cn";

type Msg = { id: number; who: "u" | "a" | "art"; text?: string; live?: boolean; art?: Artifact };
type Saved = { id: string; title: string; when: string; messages: { who: "u" | "a"; text: string }[] };

/** 画面のいちばん下まで送る。soft のときは、すでに下の方を見ているときだけ（読み返し中は邪魔しない） */
function scrollToEnd(soft = false) {
  requestAnimationFrame(() => {
    const el = document.documentElement;
    if (soft && el.scrollHeight - (window.scrollY + window.innerHeight) > 200) return;
    window.scrollTo({ top: el.scrollHeight });
  });
}

export function AiView() {
  const { tasks, setDue, undo } = useTasks();
  const reduce = useReducedMotion();
  const wide = useWide();
  const coarse = useCoarsePointer();
  const [msgs, setMsgs] = useState<Msg[]>([]);
  const [busy, setBusy] = useState(false);
  const [art, setArt] = useState<Artifact | null>(null);
  const [artOpen, setArtOpen] = useState(false);
  const [historyOpen, setHistoryOpen] = useState(false);
  const [saved, setSaved] = useState<Saved[]>(SAMPLE_HISTORY);
  const [draft, setDraft] = useState("");
  const [error, setError] = useState(false);
  const seq = useRef(0);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);

  // 画面を離れたら、届きかけの返事を止める
  useEffect(() => () => {
    if (timer.current) clearTimeout(timer.current);
  }, []);

  const ask = (q: string) => {
    if (busy) return;
    const a = answer(q, tasks);
    const id = (seq.current += 3);
    setMsgs((m) => [...m, { id, who: "u", text: q }, { id: id + 1, who: "a", text: "", live: true }]);
    setBusy(true);
    scrollToEnd();

    const finish = () => {
      timer.current = null;
      setMsgs((m) => {
        const out = m.map((x) => (x.id === id + 1 ? { ...x, text: a.text, live: false } : x));
        return a.artifact ? [...out, { id: id + 2, who: "art" as const, art: a.artifact }] : out;
      });
      if (a.artifact) setArt(a.artifact);
      setBusy(false);
      scrollToEnd(true);
    };
    if (reduce) {
      finish();
      return;
    }
    // 見本の「届く速さ」：考える間 0.38 秒 → 22ms ごとに2文字
    let i = 0;
    const tick = () => {
      i = Math.min(a.text.length, i + 2);
      setMsgs((m) => m.map((x) => (x.id === id + 1 ? { ...x, text: a.text.slice(0, i) } : x)));
      scrollToEnd(true);
      timer.current = i < a.text.length ? setTimeout(tick, 22) : null;
      if (i >= a.text.length) finish();
    };
    timer.current = setTimeout(tick, 380);
  };

  const submit = () => {
    const v = draft.trim();
    if (!v) {
      setError(true);
      inputRef.current?.focus();
      return;
    }
    if (busy) return;
    setDraft("");
    if (inputRef.current) inputRef.current.style.height = "";
    ask(v);
  };

  const openArt = (a: Artifact) => {
    setArt(a);
    if (!wide) setArtOpen(true);
  };

  const apply = (a: Artifact) => {
    const ids = [...new Set(a.items.map((x) => x.taskId).filter((x): x is number => x !== undefined))];
    setDue(ids, "today");
    setArtOpen(false);
    notify(`${ids.length}件を今日のタスクに入れました`, undo);
  };

  const copy = (a: Artifact) => {
    const text = `${a.title}\n${a.items.map((x) => `・${x.text}（${x.sub}）`).join("\n")}`;
    const fail = () => notify("コピーできませんでした。文章を選んでコピーしてください");
    try {
      navigator.clipboard.writeText(text).then(() => notify("振り返りの文章をコピーしました"), fail);
    } catch {
      fail();
    }
  };

  const newChat = () => {
    if (busy) return;
    const first = msgs.find((m) => m.who === "u");
    if (first) {
      const messages = msgs.filter((m) => m.who !== "art").map((m) => ({ who: m.who as "u" | "a", text: m.text ?? "" }));
      setSaved((s) => [{ id: `s${seq.current}`, title: first.text ?? "", when: "さっき", messages }, ...s]);
    }
    setMsgs([]);
    setArt(null);
    setHistoryOpen(false);
  };

  const openSaved = (h: Saved) => {
    if (busy) return;
    setMsgs(h.messages.map((m) => ({ id: (seq.current += 1), who: m.who, text: m.text })));
    setArt(null);
    setHistoryOpen(false);
    scrollToEnd();
  };

  return (
    <Page className="side:max-w-[1240px]">
      <PageHeader
        title="AIに相談"
        sub="見本なので、返事は決まった台本です"
        actions={
          <>
            <Button onClick={newChat} disabled={busy} aria-label="新しい会話" title="新しい会話" className="max-rail:w-hit max-rail:px-0">
              <MessageSquarePlus aria-hidden size={18} />
              <span className="max-rail:hidden">新しい会話</span>
            </Button>
            <Button onClick={() => setHistoryOpen(true)} aria-label="履歴" title="履歴" className="max-rail:w-hit max-rail:px-0">
              <History aria-hidden size={18} />
              <span className="max-rail:hidden">履歴</span>
            </Button>
          </>
        }
      />

      <div className="grid gap-6 side:grid-cols-[minmax(0,1fr)_360px] side:items-start">
        <div className="flex min-h-[calc(100dvh-150px)] min-w-0 flex-col max-rail:min-h-[calc(100dvh-var(--wk-tabbar-space)-96px)]">
          <div role="log" aria-label="会話" className="grid flex-1 content-start gap-4 pt-2 pb-4">
            {msgs.length === 0 && (
              <div className="grid gap-2 py-2">
                <Sparkles aria-hidden size={22} className="text-accent" />
                <p className="text-fg-2">タスクの並べ替えや、計画づくりを手伝います。下の候補から選ぶか、頼みたいことを書いてください。</p>
              </div>
            )}
            {msgs.map((m) =>
              m.who === "u" ? (
                <p key={m.id} className="max-w-[min(560px,88%)] justify-self-end rounded-[18px_18px_6px_18px] bg-surface-2 px-3.5 py-2.5 leading-relaxed whitespace-pre-wrap">
                  {m.text}
                </p>
              ) : m.who === "a" ? (
                <div key={m.id} aria-busy={m.live || undefined} className="max-w-[min(600px,96%)] justify-self-start leading-[1.8]">
                  <div className="mb-0.5 flex items-center gap-1.5 text-xs text-fg-3">
                    <Sparkles aria-hidden size={14} />
                    アシスタント
                  </div>
                  {m.live && !m.text ? (
                    <span className="inline-flex items-center gap-1 text-sm text-fg-3">
                      考えています
                      <span aria-hidden className="wk-dots" />
                    </span>
                  ) : (
                    <p className="whitespace-pre-wrap">
                      {m.text}
                      {m.live && <span aria-hidden className="wk-caret" />}
                    </p>
                  )}
                </div>
              ) : (
                <button
                  key={m.id}
                  type="button"
                  onClick={() => openArt(m.art!)}
                  className={cn(
                    "flex w-[min(440px,100%)] items-center gap-3 justify-self-start rounded-md border bg-surface px-3.5 py-3 text-left transition-colors duration-[var(--wk-dur-fast)] hover:bg-surface-2",
                    wide && art === m.art ? "border-accent" : "border-line",
                  )}
                >
                  <span className="grid size-9 flex-none place-items-center rounded-sm bg-accent-soft text-accent-text">
                    <FileText aria-hidden size={18} />
                  </span>
                  <span className="min-w-0 flex-1">
                    <b className="block text-sm font-semibold">{m.art!.title}</b>
                    <span className="text-xs text-fg-3">{wide ? (art === m.art ? "右のパネルに表示中" : "押すと右のパネルに出します") : "押して開く"}</span>
                  </span>
                  <ChevronRight aria-hidden size={18} className="flex-none text-fg-3" />
                </button>
              ),
            )}
          </div>

          {/* 入力欄：画面の下に貼り付く（スマホでは下タブの上） */}
          <div className="sticky bottom-[calc(var(--wk-tabbar-h)+var(--wk-tabbar-gap)*2+var(--wk-safe-b))] z-10 grid gap-2 bg-linear-to-t from-canvas from-75% to-transparent pt-4 pb-1 rail:bottom-0 rail:pb-5">
            {!busy && (
              <div className="flex gap-2 overflow-x-auto pb-0.5 [scrollbar-width:none] rail:flex-wrap">
                {SUGGESTIONS.map((s) => (
                  <button
                    key={s}
                    type="button"
                    onClick={() => ask(s)}
                    className="h-hit flex-none rounded-full border border-line bg-surface px-3.5 text-sm text-fg-2 transition-colors duration-[var(--wk-dur-fast)] hover:border-accent hover:text-accent-text"
                  >
                    {s}
                  </button>
                ))}
              </div>
            )}
            <form
              noValidate
              onSubmit={(e) => {
                e.preventDefault();
                submit();
              }}
              className="flex items-end gap-2 rounded-[20px] border border-line bg-surface py-1.5 pr-1.5 pl-4 shadow-float focus-within:border-accent"
            >
              <textarea
                ref={inputRef}
                rows={1}
                value={draft}
                onChange={(e) => {
                  setDraft(e.target.value);
                  setError(false);
                  e.target.style.height = "auto";
                  e.target.style.height = `${Math.min(140, e.target.scrollHeight)}px`;
                }}
                onKeyDown={(e) => {
                  // PC は Enter で送る（Shift+Enter で改行）。指の端末は送るボタンで送る（Enter は改行）
                  if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent.isComposing && !coarse) {
                    e.preventDefault();
                    submit();
                  }
                }}
                aria-label="AIへの依頼"
                aria-invalid={error || undefined}
                aria-describedby={error ? "ai-error" : undefined}
                placeholder="AIに頼みたいことを書く"
                className="max-h-[140px] min-h-hit min-w-0 flex-1 resize-none bg-transparent py-[calc((var(--wk-hit)-1.5em)/2)] leading-normal outline-none placeholder:text-fg-3"
              />
              <button
                type="submit"
                aria-label="送る"
                aria-disabled={busy || undefined}
                className="grid size-hit flex-none place-items-center rounded-full bg-accent text-on-accent transition-[transform,opacity] duration-[var(--wk-dur-fast)] active:scale-[0.94] aria-disabled:opacity-50"
              >
                <ArrowUp aria-hidden size={18} />
              </button>
            </form>
            {error && (
              <InlineError className="mx-2">
                <span id="ai-error">頼みたいことを書くか、上の候補から選んでください</span>
              </InlineError>
            )}
          </div>
        </div>

        {/* 右の成果物パネル（1280px 以上だけ） */}
        <aside aria-label="AIの成果物" className="sticky top-24 hidden rounded-md border border-line bg-surface p-5 side:block">
          {art ? <ArtifactView art={art} onApply={apply} onCopy={copy} /> : <EmptyState icon={Sparkles} title="AIが作った表や計画は、ここに並びます" body="下の候補から1つ頼んでみてください。" />}
        </aside>
      </div>

      <Sheet open={artOpen && !!art && !wide} onOpenChange={setArtOpen} title="AIの成果物">
        {art && <ArtifactView art={art} onApply={apply} onCopy={copy} inSheet />}
      </Sheet>

      <Sheet open={historyOpen} onOpenChange={setHistoryOpen} title="会話の履歴" description="見本なので、この画面を離れると消えます">
        <div className="grid gap-1 pb-2">
          <button type="button" onClick={newChat} className="flex min-h-row items-center gap-3 rounded-md px-3 text-left font-medium text-accent-text hover:bg-surface-2">
            <MessageSquarePlus aria-hidden size={18} />
            新しい会話を始める
          </button>
          {saved.map((h) => (
            <button key={h.id} type="button" onClick={() => openSaved(h)} className="flex min-h-row items-center gap-3 rounded-md px-3 text-left hover:bg-surface-2">
              <History aria-hidden size={18} className="flex-none text-fg-3" />
              <span className="min-w-0 flex-1 truncate text-sm">{h.title}</span>
              <span className="flex-none text-xs text-fg-3">{h.when}</span>
            </button>
          ))}
        </div>
      </Sheet>
    </Page>
  );
}

function ArtifactView({ art, onApply, onCopy, inSheet }: { art: Artifact; onApply: (a: Artifact) => void; onCopy: (a: Artifact) => void; inSheet?: boolean }) {
  return (
    <div className="grid gap-4">
      <div>
        {/* シートでは見出しに「AIの成果物」と出ているので重ねない */}
        {!inSheet && <div className="text-xs text-fg-3">AIの成果物</div>}
        <h2 className="text-lg leading-snug font-semibold">{art.title}</h2>
      </div>
      <ol className="grid gap-2.5">
        {art.items.map((x, i) => (
          <li key={i} className="flex gap-3">
            <span className="num grid size-6 flex-none place-items-center rounded-full bg-surface-2 text-xs font-semibold text-fg-2">{i + 1}</span>
            <span className="min-w-0">
              <span className="block text-sm font-medium">{x.text}</span>
              <span className="text-xs text-fg-3">{x.sub}</span>
            </span>
          </li>
        ))}
      </ol>
      {art.apply ? (
        <Button variant="primary" onClick={() => onApply(art)} className="justify-self-start max-rail:w-full max-rail:justify-self-stretch">
          <Sun aria-hidden size={16} />
          {art.apply}
        </Button>
      ) : (
        <Button onClick={() => onCopy(art)} className="justify-self-start max-rail:w-full max-rail:justify-self-stretch">
          <ClipboardCopy aria-hidden size={16} />
          文章をコピー
        </Button>
      )}
    </div>
  );
}

"use client";

/** 設定：明るさ・行の高さ・この端末の操作方法・見本データの初期化（元に戻せないので確認を挟む） */
import { useState } from "react";
import { Button } from "@/components/kit/button";
import { ConfirmDialog } from "@/components/kit/confirm-dialog";
import { Page, PageHeader } from "@/components/kit/feedback";
import { Segmented } from "@/components/kit/segmented";
import { notify } from "@/components/kit/toast";
import { PALETTES } from "@/lib/palettes";
import { setDensity, setPalette, setTheme, useCoarsePointer, useDensity, usePalette, useTheme, type Density, type Theme } from "@/lib/prefs";
import { cn } from "@/lib/cn";
import { useTasks } from "@/lib/tasks";

function Row({ title, help, children }: { title: string; help: string; children: React.ReactNode }) {
  return (
    <div className="flex flex-wrap items-center justify-between gap-3 border-b border-line py-3.5">
      <div>
        <div className="text-sm">{title}</div>
        <div className="text-xs text-fg-3">{help}</div>
      </div>
      {children}
    </div>
  );
}

export function SettingsView() {
  const theme = useTheme();
  const density = useDensity();
  const coarse = useCoarsePointer();
  const palette = usePalette();
  const darkOnly = PALETTES.find((p) => p.id === palette)?.darkOnly;
  const { reset } = useTasks();
  const [confirming, setConfirming] = useState(false);

  return (
    <Page>
      <PageHeader title="設定" sub="見た目と、この端末での使い心地" />
      <section className="mt-2" aria-labelledby="palette-h">
        <div className="mb-2 flex items-baseline justify-between gap-3">
          <h2 id="palette-h" className="text-base font-semibold">
            テーマ
          </h2>
          <span className="text-xs text-fg-3">色・文字・角の丸みがまとめて変わります</span>
        </div>
        <div role="group" aria-label="テーマ" className="grid grid-cols-1 gap-2 rail:grid-cols-2 side:grid-cols-3">
          {PALETTES.map((p) => (
            <button
              key={p.id}
              type="button"
              aria-pressed={palette === p.id}
              onClick={() => setPalette(p.id)}
              className={cn(
                "flex min-h-row items-center gap-3 rounded-md border bg-surface px-3 py-2.5 text-left transition-colors duration-[var(--wk-dur-fast)] hover:bg-surface-2",
                palette === p.id ? "border-accent ring-1 ring-accent" : "border-line",
              )}
            >
              <span aria-hidden className="grid flex-none grid-cols-2 overflow-hidden rounded-sm border border-line">
                {p.swatch.map((c, i) => (
                  <i key={i} className="block size-3.5" style={{ background: c }} />
                ))}
              </span>
              <span className="min-w-0">
                <b className="block text-sm font-semibold">{p.label}</b>
                <span className="block text-xs text-fg-3">{p.desc}</span>
              </span>
            </button>
          ))}
        </div>
      </section>
      <section className="mt-8">
        <h2 className="mb-1 text-base font-semibold">表示</h2>
        <Row title="明るさ" help={darkOnly ? "このテーマは常に暗い表示です" : "端末の設定に合わせるか、固定するか"}>
          <Segmented<Theme>
            label="明るさ"
            value={theme}
            onChange={setTheme}
            options={[
              { value: "system", label: "端末に合わせる" },
              { value: "light", label: "ライト" },
              { value: "dark", label: "ダーク" },
            ]}
          />
        </Row>
        <Row title="行の高さ" help="詰めると一覧に多く並びます（指で触る端末では詰めすぎない）">
          <Segmented<Density>
            label="行の高さ"
            value={density}
            onChange={setDensity}
            options={[
              { value: "comfy", label: "ゆったり" },
              { value: "compact", label: "詰める" },
            ]}
          />
        </Row>
        <Row title="この端末の操作" help="ボタンの大きさは画面幅ではなく「指かマウスか」で決めています">
          <b className="text-sm font-medium">{coarse ? "指（ボタン 44px）" : "マウス（ボタン 36px）"}</b>
        </Row>
      </section>
      <section className="mt-8">
        <h2 className="mb-1 text-base font-semibold">データ</h2>
        <Row title="見本データに戻す" help="追加・完了・削除した内容が消えます。元に戻せません">
          <Button variant="danger" onClick={() => setConfirming(true)}>
            見本データに戻す
          </Button>
        </Row>
      </section>
      <ConfirmDialog
        open={confirming}
        onOpenChange={setConfirming}
        title="見本データに戻しますか？"
        body="追加・完了・削除した内容はすべて消え、元に戻せません。"
        confirmLabel="戻す"
        onConfirm={() => {
          reset();
          notify("見本データに戻しました");
        }}
      />
    </Page>
  );
}

"use client";

/**
 * タスク一覧（A 指令室型）。
 *   1280px 以上 … 一覧の表＋右の詳細パネル（↑↓ キーで選ぶ、… でメニュー）
 *   それより狭い … カードに近い行。押すと詳細シート、長押し（指）で操作シート
 * 絞り込みと選んだタスクは URL に入れる（?f=today&id=3）。再読み込み・共有・戻るで同じ画面に戻れる。
 */
import { CheckCheck, CircleCheck, Plus, Search } from "lucide-react";
import { useSearchParams } from "next/navigation";
