type Store = {
  tasks: Task[];
  toggle: (id: number) => Task | undefined;
  /** 期限を変える（今日に入れる・明日に回す） */
  setDue: (ids: number[], due: Due) => void;
  add: (t: Omit<Task, "id" | "done">) => Task;
  remove: (id: number) => Task | undefined;
  reset: () => void;
  /** 直前の変更を1つ戻す（トーストの「取り消す」用） */
  undo: () => void;
};

const Ctx = createContext<Store | null>(null);

export function TaskProvider({ children }: { children: React.ReactNode }) {
  // prev は「取り消す」で戻す1つ前の状態
  const [state, setState] = useState<{ tasks: Task[]; prev: Task[] | null; seq: number }>({ tasks: SAMPLE, prev: null, seq: 100 });
  const change = useCallback((f: (tasks: Task[]) => Task[]) => setState((s) => ({ ...s, tasks: f(s.tasks), prev: s.tasks })), []);
  const { tasks } = state;

  const store = useMemo<Store>(
    () => ({
      tasks,
      toggle: (id) => {
        const t = tasks.find((x) => x.id === id);
        change((ts) => ts.map((x) => (x.id === id ? { ...x, done: !x.done } : x)));
        return t && { ...t, done: !t.done };
      },
      setDue: (ids, due) => change((ts) => ts.map((x) => (ids.includes(x.id) && !x.done ? { ...x, due } : x))),
      add: (t) => {
        const task: Task = { ...t, id: state.seq + 1, done: false };
        setState((s) => ({ tasks: [task, ...s.tasks], prev: s.tasks, seq: s.seq + 1 }));
        return task;
      },
      remove: (id) => {
        const t = tasks.find((x) => x.id === id);
        change((ts) => ts.filter((x) => x.id !== id));
        return t;
      },
      reset: () => setState((s) => ({ ...s, tasks: SAMPLE, prev: null })),
      undo: () => setState((s) => (s.prev ? { ...s, tasks: s.prev, prev: null } : s)),
    }),
    [tasks, state.seq, change],
  );

  return <Ctx.Provider value={store}>{children}</Ctx.Provider>;
}

export function useTasks() {
  const s = useContext(Ctx);
  if (!s) throw new Error("useTasks は TaskProvider の中で使う");
  return s;
}

export function counts(tasks: Task[]) {
  const open = tasks.filter((t) => !t.done);
  return {
    open: open.length,
    today: open.filter((t) => t.due === "today").length,
    overdue: open.filter((t) => t.due === "overdue").length,
    done: tasks.filter((t) => t.done).length,
  };
}

import { ListChecks, Settings2, Sparkles, Sun, type LucideIcon } from "lucide-react";

/**
 * 画面の切り替え（ナビ）の項目。ここを書き換えると、サイドバー・アイコン列・下タブの全部が同じ順番で変わる。
 * - label: サイドバーに出す名前
 * - short: 下タブに出す短い名前（全角4文字まで）
 * - 下タブに出るのは先頭5つまで。6つ以上か config/shell.tsx の useAccount があるときは、先頭4つ＋「もっと」（残りは中のシート）
 */
export type NavItem = { href: string; label: string; short: string; icon: LucideIcon };

export const NAV: NavItem[] = [
  { href: "/", label: "今日", short: "今日", icon: Sun },
  { href: "/tasks", label: "タスク", short: "タスク", icon: ListChecks },
  { href: "/ai", label: "AIに相談", short: "AI", icon: Sparkles },
  { href: "/settings", label: "設定", short: "設定", icon: Settings2 },
];

/** 今の場所がその項目の中か（"/" は完全一致、それ以外は配下も含む） */
export function isActive(pathname: string, href: string) {
  return href === "/" ? pathname === "/" : pathname === href || pathname.startsWith(href + "/");
}

"use client";

/**
 * 骨組み（ナビ・⌘K パレット・追加ボタン）と、このアプリの中身をつなぐ場所。
 * 骨組み（components/shell/）は触らず、アプリごとに変えるのはこのファイルと config/nav.ts だけにする。
 *
 * - APP           … サイドバーの左上に出す名前と頭文字、追加ボタンと ⌘K の入力欄の文言
 * - ShellProviders … 骨組みの外側で包みたい物（データの入れ物など）。無ければ children をそのまま返す
 * - AddSheet      … 「追加」ボタン・N キー・⌘K の「追加」で開くシート。追加が無いアプリは null にする
 * - useExtraCommands … ⌘K パレットに足す候補（打った文字で絞り込む）。無ければ空の配列を返す
 * - useAccount   … ナビの一番下に出す「ログイン中の人」と操作（ログアウトなど）。無ければ null。スマホでは下タブの「もっと」の中に出る
 */
import { ListChecks } from "lucide-react";
import { useRouter } from "next/navigation";
import { AddTaskSheet } from "@/components/tasks/add-task-sheet";
import type { AccountInfo, PaletteItem } from "@/components/shell/command-palette";
import { TaskProvider, useTasks } from "@/lib/tasks";

export const APP = {
  name: "Kit タスク帳",
  mark: "K",
  addLabel: "タスクを追加",
  searchLabel: "タスクを探す・操作を選ぶ",
};

export function ShellProviders({ children }: { children: React.ReactNode }) {
  return <TaskProvider>{children}</TaskProvider>;
}

export const AddSheet: React.ComponentType<{ open: boolean; onOpenChange: (open: boolean) => void }> | null = AddTaskSheet;

/** needle … 打った文字（小文字・前後の空白なし）。空のときは「よく使う物」を少しだけ返す */
export function useExtraCommands(needle: string): PaletteItem[] {
  const router = useRouter();
  const { tasks } = useTasks();
  const hit = (s: string) => s.toLowerCase().includes(needle);
  return tasks
    .filter((t) => (needle ? hit(t.title) || hit(t.project) : !t.done))
    .slice(0, needle ? 8 : 4)
    .map((t) => ({
      id: `task-${t.id}`,
      group: needle ? "タスク" : "未完了のタスク",
      label: t.title,
      hint: t.project,
      icon: ListChecks,
      run: () => router.push(`/tasks?id=${t.id}${t.done ? "&f=done" : ""}`),
    }));
}

/** ログインのあるアプリは、ここでログイン中の人の名前（メールなど）と操作を返す */
export function useAccount(): AccountInfo | null {
  return null;
}

